 timing::Executor e;IO io;timing::Command c;c.angle=engine::angle_config(tune);c.sequence=1;c.tune_revision=c.sensor_revision=c.configuration_epoch=1;c.command_us=c.sampled_us=1;c.output=o;c.output.rpm=1000;c.output.pulse_ms=8;e.progress(1,io);e.command(c,1,io);timing::Executor::Candidate invalid;e.prepare(invalid,2,20000);invalid.calculate(0,8000);assert(!invalid.valid&&e.commit(invalid,2,io)==timing::Executor::Commit::Fault&&e.stats().fault==timing::Cause::Plan&&!io.mask);
 timing::Executor fenced;IO outputs;c.angle=engine::angle_config(tune);c.output.pulse_ms=1;c.output.dwell_ms=1;c.output.rpm=1000;c.sequence=0;timing::Executor::Candidate old;
 for(unsigned n=0;n<=13;++n){const std::uint64_t now=1+n*1000;while(fenced.next_alarm()<=now)fenced.dispatch(fenced.next_alarm(),outputs);c.command_us=c.sampled_us=now;++c.sequence;fenced.progress(now,outputs);fenced.command(c,now,outputs);timing::Executor::Candidate planned;fenced.prepare(planned,now,20000);planned.calculate(n,1000);assert(fenced.commit(planned,now,outputs)==timing::Executor::Commit::Accepted);if(n==12)old=planned;}
 while(fenced.next_alarm()<=14001){fenced.dispatch(fenced.next_alarm(),outputs);}
