 engine::AngleScheduler hard;engine::Output coast;coast.state=engine::State::Running;coast.rpm=1000;coast.pulse_ms=1;coast.dwell_ms=2.8;coast.advance_deg=10;std::uint64_t first_rise=0;
 for(unsigned n=0;n<=11;++n){const auto now=std::uint64_t(n*1000);while(hard.next_time()<=now){engine::Edge edge;assert(hard.pop(edge));if(edge.channel>=4&&edge.high)first_rise=edge.time_us;}assert(hard.tooth(tune,coast,now,n,60,now,now));}
 assert(first_rise&&13000-first_rise<3500);coast.rpm=500;assert(!hard.tooth(tune,coast,13000,12,60,13000,13000)&&hard.stop_reason()==engine::AngleScheduler::StopReason::DwellLimit);
 std::cout<<"{\"duty_exact_and_nextafter_boundaries\":true,\"max15ms_boundary\":true,\"trims_and_unknown_strategy_rejected\":true,\"fresh_tooth_RPM_rechecks_duty\":true,\"hot_mode_cuts_active_outputs\":true,\"old_candidate_retries_after_mode_fence\":true,\"hard_deceleration_dwell_limit\":true,\"actual_charge_at_guard_us\":"<<13000-first_rise<<"}\n";
